using LedgerFlow.Api.Models;using LedgerFlow.Api.Services;namespace LedgerFlow.Api.Tests;public sealed class ReconciliationServiceTests{private readonly ReconciliationService _sut=new();[Fact]public void Positive_valid_transaction_is_matched(){var tx=new Transaction{Reference="T-1",Account="100200",Amount=125.50m,BookedAt=DateTimeOffset.UtcNow};Assert.Equal(TransactionStatus.Matched,_sut.Evaluate(tx).Status);}[Fact]public void Non_positive_amount_is_exception(){var tx=new Transaction{Reference="T-2",Account="100200",Amount=0m,BookedAt=DateTimeOffset.UtcNow};Assert.Equal(TransactionStatus.Exception,_sut.Evaluate(tx).Status);}}
